# Bossify — Pro/Business feature-gating batch apply
# Generated by Claude — writes 8 changed files, then commits/pushes/deploys in one go.
$ErrorActionPreference = 'Stop'

Set-Location "C:\Users\user\Projects\bossify"

Write-Host '== git pull ==' -ForegroundColor Cyan
git pull

$files = @{}
$files['src/lib/featureFlags.ts'] = ''
$files['src/routes/campaigns_.$campaignId.tsx'] = ''
$files['src/contexts/SubscriptionContext.tsx'] = ''
$files['src/contexts/I18nContext.tsx'] = ''
$files['src/routes/reports.index.tsx'] = ''
$files['src/routes/cost-breakdown.tsx'] = ''
$files['src/routes/product-profit.tsx'] = ''
$files['src/components/UpgradeModal.tsx'] = ''

Write-Host '== writing files ==' -ForegroundColor Cyan
foreach ($path in $files.Keys) {
  $dir = Split-Path $path -Parent
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  $bytes = [System.Convert]::FromBase64String($files[$path])
  [System.IO.File]::WriteAllBytes($path, $bytes)
  Write-Host "  wrote $path"
}
Write-Host "$($files.Count) files written." -ForegroundColor Green

Write-Host '== git commit + push ==' -ForegroundColor Cyan
git add -A
git commit -m "Pro/Business feature gating: report tiers, 3-month history cap, hide campaign AI, raise free product limit"
git push

Write-Host '== deploy ==' -ForegroundColor Cyan
npm run build
npx nitro deploy --prebuilt
npx cap sync android
Set-Location "android"
./gradlew assembleDebug

Write-Host 'All done.' -ForegroundColor Green
